function Inbox(){const c=useEng(),[selected,setSelected]=useState(''),[query,setQuery]=useState(''),[filter,setFilter]=useState('All'),[newLead,setNewLead]=useState(''),[body,setBody]=useState(''),[material,setMaterial]=useState(''),[note,setNote]=useState(''),[fixture,setFixture]=useState('');const conversations=c.of('conversation'),rows=conversations.filter((r:any)=>{const l=c.leads.find((v:any)=>v.id===r.leadId);return (filter==='All'||r.data.state===filter)&&[l?.data.name,l?.data.phone,r.data.summary].join(' ').toLowerCase().includes(query.toLowerCase());}),conv=conversations.find((r:any)=>r.leadId===selected)||null,lead=c.leads.find((l:any)=>l.id===selected),messages=c.of('message').filter((r:any)=>r.leadId===selected).sort((a:any,b:any)=>a.createdAt.localeCompare(b.createdAt)),materials=c.of('knowledge').filter((r:any)=>r.data.status==='Approved'&&r.data.validUntil>=isoDay()&&r.data.url),callbacks=c.of('callback').filter((r:any)=>r.leadId===selected),bookings=[...c.of('booking'),...c.of('bookingRequest')].filter((r:any)=>r.leadId===selected);useEffect(()=>{if(!selected&&rows.length)setSelected(rows[0].leadId);},[rows.length]);return <><Panel title="WhatsApp Inbox" detail="A shared conversation history with explicit AI handback and counsellor ownership." actions={<a className="btn" href={`/?view=settings&workspace=${c.scope}`}>Integration setup<ArrowUpRight size={14}/></a>}><div className="eng-notice"><ShieldCheck size={17}/><span>{c.settings.aiEnabled&&c.settings.enabled?'AI replies run only in conversations explicitly handed to AI.':'AI autopilot is inactive. Conversations, notes, assignments and requests are available.'} Provider submission never means confirmed delivery.</span></div><div className="eng-inbox"><aside className="eng-conversation-list"><div className="eng-list-tools"><input aria-label="Search WhatsApp conversations" placeholder="Search name, phone or summary…" value={query} onChange={e=>setQuery(e.target.value)}/><Select label="Conversation state filter" value={filter} onChange={setFilter} options={['All','AI','Paused','Human']}/></div>{rows.map((r:any)=>{const l=c.leads.find((v:any)=>v.id===r.leadId);return <button className={'eng-conversation '+(selected===r.leadId?'selected':'')} key={r.id} onClick={()=>setSelected(r.leadId)}><span className="eng-avatar">{l?.data.name?.slice(0,1)||'S'}</span><span><strong>{l?.data.name||'Student'}</strong><small>{r.data.summary||l?.data.phone||'No messages yet'}</small><Badge>{r.data.state}</Badge></span></button>;})}{!rows.length&&<Empty>No conversations match.</Empty>}<div className="eng-list-tools"><Select label="Start conversation for student" value={newLead} onChange={setNewLead} options={[{value:'',label:'Select a student'},...c.leads.map((l:any)=>({value:l.id,label:l.data.name}))]}/><button className="btn" disabled={!newLead||!c.canEdit} onClick={async()=>{await c.act({action:'conversation',leadId:newLead,state:'Paused'},'Conversation created');setSelected(newLead);}}>Open conversation</button></div></aside><div className="eng-chat">{lead&&conv?<><div className="eng-chat-head"><div><h4>{lead.data.name}</h4><small>{lead.data.phone} · {conv.data.owner}</small></div><Badge>{conv.data.state==='AI'?'AI enabled':conv.data.state==='Human'?'Human handling':'AI paused'}</Badge></div><div className="eng-takeover"><button className="btn small-btn" disabled={!c.canEdit||c.busy} onClick={()=>c.act({action:'conversation',leadId:selected,state:'Human',owner:conv.data.owner},'Human takeover active')}>Take over</button><button className="btn small-btn" disabled={!c.canEdit||c.busy} onClick={()=>c.act({action:'conversation',leadId:selected,state:'Paused',owner:conv.data.owner},'AI paused')}>Pause AI</button><button className="btn small-btn" disabled={!c.canEdit||c.busy} onClick={()=>c.setInspect({type:'handback',lead})}>Hand back to AI</button><Select label="Conversation owner" value={conv.data.owner||'Unassigned'} options={c.ownerOptions.includes(conv.data.owner)?c.ownerOptions:[conv.data.owner,...c.ownerOptions]} onChange={(owner:string)=>c.act({action:'conversation',leadId:selected,state:conv.data.state,owner},'Conversation assigned')}/></div><div className="eng-messages">{messages.map((r:any)=><article className={'eng-message '+(r.data.direction==='Outbound'?'outbound':'')} key={r.id}><small>{r.data.direction} · {r.data.source||r.data.channel}</small><p>{r.data.body}</p><footer><span>{format(r.data.timestamp||r.createdAt)}</span><Badge>{r.data.status}</Badge></footer></article>)}{!messages.length&&<Empty>Verified inbound messages and queued provider submissions will appear here.</Empty>}</div><div className="eng-composer"><Select label="Attach approved brochure" value={material} onChange={setMaterial} options={[{value:'',label:'Approved brochure / link'},...materials.map((r:any)=>({value:r.id,label:r.data.name}))]}/><textarea aria-label="WhatsApp reply" placeholder="Take over to compose a counsellor reply…" disabled={conv.data.state!=='Human'||!c.canEdit} value={body} onChange={e=>setBody(e.target.value)}/><div className="eng-card-foot"><small>Freeform replies require an open 24-hour service window. Queued replies wait for an enabled provider.</small><button className="btn primary" disabled={!body.trim()||conv.data.state!=='Human'||c.busy||!c.canEdit} onClick={async()=>{const r=await c.act({action:'reply',leadId:selected,body,materialId:material,requestId:requestId()},'Reply queued; delivery pending');if(r)setBody('');}}><Send size={14}/>Queue reply</button></div></div></>:<Empty>Select or open a student conversation.</Empty>}</div>{lead&&<aside className="eng-chat-profile"><h4>Student profile</h4><dl>{[['Stage',lead.data.stage],['Destination',lead.data.country],['Course',lead.data.course||'Not recorded'],['Intake',lead.data.intake],['Owner',lead.data.owner]].map(([k,v])=><div key={k}><dt>{k}</dt><dd>{v}</dd></div>)}</dl><div className="eng-profile-actions"><button className="btn" disabled={!c.canEdit} onClick={()=>c.setInspect({type:'callback',lead})}><Phone size={14}/>Create callback</button><button className="btn" disabled={!c.canEdit} onClick={()=>c.setInspect({type:'booking',lead})}><CalendarDays size={14}/>Book Mentor Session</button></div><h4>Conversation summary</h4><p className="muted">{conv?.data.summary||'No summary recorded.'}</p><h4>Linked actions</h4>{callbacks.map((r:any)=><div className="eng-small-record" key={r.id}><strong>Staff callback · {r.data.owner}</strong><small>{format(r.data.dueAt,r.data.timezone)} · {r.data.timezone}</small><Badge>{r.data.status}</Badge></div>)}{bookings.map((r:any)=><div className="eng-small-record" key={r.id}><strong>Mentor Session</strong><small>{r.data.start?format(r.data.start,r.data.timezone):'Awaiting staff confirmation'}</small><Badge>{r.data.status}</Badge></div>)}<h4>Internal notes</h4>{c.of('internalNote').filter((r:any)=>r.leadId===selected).map((r:any)=><div className="eng-small-record" key={r.id}><p>{r.data.body}</p><small>{r.data.author} · {format(r.createdAt)}</small></div>)}<textarea aria-label="Internal conversation note" placeholder="Private staff note…" value={note} onChange={e=>setNote(e.target.value)}/><button className="text-button" disabled={!note.trim()||!c.canEdit} onClick={async()=>{const r=await c.act({action:'note',leadId:selected,body:note},'Internal note saved');if(r)setNote('');}}>Save note</button>{c.scope==='demo'&&c.admin&&<details className="eng-disclosure"><summary>Isolated inbound test fixture</summary><textarea aria-label="Test inbound message" placeholder="A fictional student message" value={fixture} onChange={e=>setFixture(e.target.value)}/><button className="btn small-btn" disabled={!fixture||c.busy} onClick={async()=>{const r=await c.act({action:'testInbound',leadId:selected,body:fixture,requestId:requestId()},'Fictional inbound recorded');if(r)setFixture('');}}>Record test inbound</button><small>No WhatsApp provider event is implied.</small></details>}</aside>}</div></Panel></>;}
