function IntegrationForm({name}:any){const c=useEng(),saved=c.integrations.find((r:any)=>r.name===name)||{name,enabled:false,mode:'Test',config:{}},[f,setF]=useState<any>({name,enabled:saved.enabled,mode:saved.mode,config:{version:'v25.0',...saved.config}}),m=integrationMeta[name];useEffect(()=>{setF({name,enabled:saved.enabled||false,mode:saved.mode||'Test',config:{...(['whatsapp','meta'].includes(name)?{version:'v25.0'}:{}),...saved.config}});},[name]);const set=(k:string,v:any)=>setF({...f,config:{...f.config,[k]:v}});return <form onSubmit={async e=>{e.preventDefault();await c.act({action:'save',type:'integration',data:f},'Connection configuration saved');}}><div className="eng-form-grid">{m.fields.map(([key,label]:string[])=><Field label={label} key={key}>{key==='interval'?<Select label={label} value={f.config[key]||5} onChange={(v:string)=>set(key,Number(v))} options={[1,5,10,15,30].map(v=>({value:v,label:v+' minutes'}))}/>:<input aria-label={label} type={['headerRow','startHour','endHour','duration'].includes(key)?'number':'text'} placeholder={key==='timezone'?'Asia/Kolkata':key==='actionSource'?'other':''} value={f.config[key]??''} onChange={e=>set(key,['headerRow','startHour','endHour','duration'].includes(key)?Number(e.target.value):e.target.value)}/>}</Field>)}<Field label="Connection mode"><Select label={m.title+' connection mode'} value={f.mode} options={['Test','Live']} onChange={(mode:string)=>setF({...f,mode})}/></Field>{name==='meta'&&milestones.map(label=><Field key={label} label={label+' → Meta event'}><input aria-label={label+' Meta mapping'} placeholder={label==='Inquiry received'?'Lead':label==='Mentor Session booked'?'Schedule':label==='Student enrolled'?'CompleteRegistration':'Leave unmapped until configured'} value={f.config['map_'+label]||''} onChange={e=>set('map_'+label,e.target.value)}/></Field>)}</div><label className="eng-check"><input type="checkbox" checked={f.enabled} onChange={e=>setF({...f,enabled:e.target.checked})}/>Enable {m.title} after setup</label><div className="eng-actions"><button className="btn primary" disabled={c.busy}>Save connection</button><small>Saving an enabled connection does not enable workspace outreach.</small></div></form>;}
