function InspectDialog(){const c=useEng(),v=c.inspect,[error,setError]=useState(''),[busy,setBusy]=useState(false),[preview,setPreview]=useState<any>(null),[testLead,setTestLead]=useState(''),[day,setDay]=useState(isoDay(new Date(Date.now()+86400000))),[time,setTime]=useState('14:00'),[tz,setTz]=useState(c.of('consent').find((r:any)=>r.leadId===v.lead?.id)?.data.timezone||'Asia/Kolkata'),[owner,setOwner]=useState(v.lead?.data.owner||'Unassigned'),[message,setMessage]=useState(''),[slots,setSlots]=useState<any[]>([]),[result,setResult]=useState<any>(null);const close=()=>c.setInspect(null),doAction=async(body:any,success:string,closeAfter=true)=>{setBusy(true);setError('');try{const d=await c.mutate(body);toast.success(success);if(closeAfter)close();else setResult(d);return d;}catch(e:any){setError(e.message);}finally{setBusy(false);}};useEffect(()=>{if(v.type==='campaign')c.mutate({action:'audience',data:{channel:v.record.data.channel,filters:v.record.data.filters,leadIds:v.record.data.leadIds,purpose:v.record.data.purpose||'Marketing'}},false).then(setPreview).catch((e:any)=>setError(e.message));},[]);const title=v.type==='campaign'?'Review broadcast':v.type==='cancelCampaign'?'Cancel remaining campaign sends':v.type==='callback'?'Schedule staff callback':v.type==='booking'?'Book a Mentor Session':v.type==='handback'?'Hand back to Student ID AI':'Job diagnostics';return <Dialog open onOpenChange={o=>{if(!o&&!busy)close();}}><DialogContent className="record-dialog eng-editor"><DialogHeader><DialogTitle>{title}</DialogTitle><DialogDescription>{v.record?.data.name||v.lead?.data.name||'Saved action details and current processing state.'}</DialogDescription></DialogHeader><div className="eng-editor-body">{v.type==='campaign'&&<><div className="eng-card-top"><Badge>{v.record.data.mode}</Badge><Badge>{v.record.data.status}</Badge></div><p>{v.record.data.channel==='email'?v.record.data.subject:v.record.data.channel==='whatsapp'?'WhatsApp template: '+v.record.data.templateId:v.record.data.objective||v.record.data.channel+' campaign'}</p><p className="eng-message-preview">{v.record.data.body}</p>{preview&&<AudiencePreview data={preview}/>}<p className="eng-notice">This audience is rechecked before every send. Existing submitted actions may complete after a pause or cancellation. Attribution uses the last CRM campaign submission before the milestone, within {v.record.data.attributionDays} days; it is an association, not proof of causation.</p>{v.record.data.status==='Draft'&&<><Field label="Isolated test student"><Select label="Isolated test student" value={testLead} onChange={setTestLead} options={[{value:'',label:'Choose test student'},...c.leads.map((l:any)=>({value:l.id,label:l.data.name}))]}/></Field><div className="eng-actions"><button className="btn" disabled={busy||!testLead||!c.manager} onClick={()=>doAction({action:'queueCampaign',id:v.record.id,testOnly:true,testLeadId:testLead},'Dry-run jobs queued')}>Queue test dry run</button><button className="btn" disabled={busy||!testLead||!c.canPublish||c.scope!=='live'||!c.settings.enabled} onClick={()=>doAction({action:'queueCampaign',id:v.record.id,testOnly:true,liveTest:true,testLeadId:testLead},'Single-recipient provider test queued')}>Send provider test</button><button className="btn primary" disabled={busy||!preview?.eligible||!(v.record.data.mode==='Test'?c.manager:c.canPublish)} onClick={()=>doAction({action:'queueCampaign',id:v.record.id},v.record.data.mode==='Test'?'Test campaign queued':'Live campaign queued; current activation controls apply')}><Send size={14}/>Queue {v.record.data.mode==='Test'?'test':'live'} campaign</button></div></>}<JobTable campaignId={v.record.id}/></>}{v.type==='cancelCampaign'&&<><p>Cancel jobs that have not crossed the provider dispatch boundary. Submitted actions retain their actual delivery history.</p><button className="btn primary" disabled={busy||!c.manager} onClick={()=>doAction({action:'campaignState',id:v.record.id,status:'Cancelled'},'Remaining campaign jobs cancelled')}>Cancel remaining sends</button></>}{v.type==='handback'&&<><p>Resume the assistant for this conversation. It will use approved current content and recheck consent and the service window. Workspace AI controls still apply.</p><button className="btn primary" disabled={busy||!c.canEdit} onClick={()=>doAction({action:'conversation',leadId:v.lead.id,state:'AI',owner:v.lead.data.owner},'Conversation explicitly handed back to AI')}>Confirm handback to AI</button></>}{['callback','booking'].includes(v.type)&&<><div className="eng-form-grid"><Field label="Student timezone"><input aria-label="Action student timezone" value={tz} onChange={e=>setTz(e.target.value)}/></Field><Field label="Date"><input aria-label="Action date" type="date" value={day} onInput={e=>setDay(e.currentTarget.value)} onChange={e=>setDay(e.target.value)}/></Field>{v.type==='callback'&&<><Field label="Time"><input aria-label="Callback local time" type="time" value={time} onInput={e=>setTime(e.currentTarget.value)} onChange={e=>setTime(e.target.value)}/></Field><Field label="Counsellor"><input aria-label="Callback counsellor" value={owner} onChange={e=>setOwner(e.target.value)}/></Field></>}</div><Field label="Request / notes"><textarea aria-label="Action request notes" value={message} onChange={e=>setMessage(e.target.value)}/></Field>{v.type==='callback'?<button className="btn primary" disabled={busy||!c.canEdit} onClick={()=>{try{doAction({action:'callback',leadId:v.lead.id,requestId:requestId(),data:{dueAt:zonedInstant(day,time,tz),timezone:tz,owner,message}},'Staff callback created');}catch(e:any){setError(e.message);}}}>Create staff callback</button>:<><div className="eng-actions"><button className="btn" disabled={busy||!c.canEdit} onClick={async()=>{setBusy(true);setError('');try{const d=await c.mutate({action:'slots',leadId:v.lead.id,date:day,timezone:tz},false);setSlots(d.slots);if(!d.slots.length)setError('No confirmed free slots on this date.');}catch(e:any){setError(e.message);}finally{setBusy(false);}}}>Check calendar availability</button><button className="btn" disabled={busy||!c.canEdit} onClick={()=>doAction({action:'bookingRequest',leadId:v.lead.id,message,requestId:requestId()},'Booking request saved; staff confirmation required')}>Save staff booking request</button></div><div className="eng-slot-grid">{slots.map(s=><button className="btn" key={s.id} disabled={busy} onClick={()=>doAction({action:'booking',leadId:v.lead.id,data:{start:s.start,timezone:tz},requestId:requestId()},'Booking action saved; see its confirmed state',false)}>Confirm {format(s.start,tz)}</button>)}</div>{result&&<div className="eng-notice"><CheckCircle2 size={17}/><span>{result.data?.status==='Booked'?'Mentor Session confirmed: '+format(result.data.start,result.data.timezone):'Booking request saved. A session time is not yet confirmed.'}</span></div>}<p className="muted">The stage changes only after the calendar booking succeeds. A request alone does not create a confirmed session.</p></>}</>}{v.type==='job'&&<><div className="eng-card-top"><strong>{v.job.kind}</strong><Badge>{v.job.status}</Badge></div><p>{v.job.reason||'No failure reason.'}</p><dl><div><dt>Due</dt><dd>{format(v.job.run_at)}</dd></div><div><dt>Attempts</dt><dd>{v.job.attempts} / {v.job.max_attempts}</dd></div></dl><pre className="eng-code">{JSON.stringify({request:v.job.data,result:v.job.result},null,2)}</pre>{['failed','blocked'].includes(v.job.status)&&<button className="btn" disabled={!c.admin||busy} onClick={()=>doAction({action:'retryJob',id:v.job.id},'Retry queued; current eligibility will be checked')}>Request controlled retry</button>}{v.job.status==='unknown'&&<p className="eng-notice warning">This submission may already exist at the provider. Check its dashboard before making a new send; automatic retry is blocked.</p>}</>}{error&&<p className="form-error" role="alert">{error}</p>}</div><div className="dialog-actions"><button className="btn" onClick={close}>Close</button></div></DialogContent></Dialog>;}
function JobTable({leadId,campaignId}:any){const c=useEng(),[query,setQuery]=useState(''),[status,setStatus]=useState('All'),[page,setPage]=useState(1),rows=c.jobs.filter((j:any)=>(!leadId||j.lead_id===leadId)&&(!campaignId||j.data.campaignId===campaignId)&&(status==='All'||j.status===status)&&[j.reason,j.kind,c.leads.find((l:any)=>l.id===j.lead_id)?.data.name].join(' ').toLowerCase().includes(query.toLowerCase())),pages=Math.max(1,Math.ceil(rows.length/20)),visible=rows.slice((Math.min(page,pages)-1)*20,Math.min(page,pages)*20);return <div className="eng-job-table"><div className="eng-table-tools"><input aria-label="Search outreach jobs" placeholder="Search student, action or reason…" value={query} onChange={e=>{setQuery(e.target.value);setPage(1);}}/><Select label="Job status filter" value={status} onChange={(v:string)=>{setStatus(v);setPage(1);}} options={['All','queued','blocked','submitted','delivered','read','completed','accepted','retry','failed','suppressed','cancelled','tested','unknown']}/><button className="icon-button" aria-label="Export loaded outreach jobs" onClick={()=>exportRecords(c.scope,'engagement','',rows.map((j:any)=>j.id),'Student-ID-Outreach-History.csv')}><Download size={16}/></button></div><Table><TableHeader><TableRow>{['Student / action','State','Due','Reason',''].map(v=><TableHead key={v}>{v}</TableHead>)}</TableRow></TableHeader><TableBody>{visible.map((j:any)=><TableRow key={j.id}><TableCell><strong>{c.leads.find((l:any)=>l.id===j.lead_id)?.data.name||'Student'}</strong><small className="block muted">{j.kind} · {j.data.mode||'Internal action'}</small></TableCell><TableCell><Badge>{j.status}</Badge></TableCell><TableCell>{format(j.run_at)}</TableCell><TableCell className="eng-reason">{j.reason||j.result.providerId||j.result.eventId||'—'}</TableCell><TableCell><button className="text-button" onClick={()=>c.setInspect({type:'job',job:j})}>Details</button></TableCell></TableRow>)}</TableBody></Table>{!rows.length&&<Empty>No matching processing history.</Empty>}<div className="eng-pagination"><small>{rows.length} shown from the latest {c.limits?.jobs||500} jobs · page {Math.min(page,pages)} / {pages}</small><div className="button-row"><button className="btn small-btn" disabled={page<=1} onClick={()=>setPage(page-1)}>Previous</button><button className="btn small-btn" disabled={page>=pages} onClick={()=>setPage(page+1)}>Next</button></div></div></div>;}
export function EngagementReports(){return <Frame><OutreachReports/></Frame>;}
function OutreachReports(){const c=useEng(),[from,setFrom]=useState(''),[to,setTo]=useState(''),inRange=(d:string)=>(!from||d.slice(0,10)>=from)&&(!to||d.slice(0,10)<=to),filtered=c.jobs.filter((j:any)=>inRange(j.created_at)),counts=from||to?filtered.reduce((o:any,j:any)=>(o[j.status]=(o[j.status]||0)+1,o),{}):c.counts.reduce((o:any,j:any)=>(o[j.status]=(o[j.status]||0)+j.count,o),{}),runs=c.of('journeyRun'),attributions=c.of('attribution').filter((r:any)=>inRange(r.data.occurredAt));return <><Panel title="Journey, campaign & AI performance" detail="Provider evidence and recorded CRM milestones, with no simulated live successes."><div className="eng-table-tools"><Field label="From"><input aria-label="Outreach report from" type="date" value={from} onChange={e=>setFrom(e.target.value)}/></Field><Field label="To"><input aria-label="Outreach report to" type="date" value={to} onChange={e=>setTo(e.target.value)}/></Field><button className="text-button" onClick={()=>{setFrom('');setTo('');}}>All time</button></div>{(from||to)&&<p className="eng-notice">Date filters apply to the latest 500 loaded jobs and recorded attributions. All-time state counts cover the full job store.</p>}<div className="eng-stat-grid six">{[['Queued',(counts.queued||0)+(counts.retry||0)+(counts.blocked||0)],['Submitted',counts.submitted||0],['Delivered',(counts.delivered||0)+(counts.read||0)],['Failed',counts.failed||0],['Suppressed',(counts.suppressed||0)+(counts.cancelled||0)],['Dry runs',counts.tested||0]].map(([name,value])=><div key={name}><small>{name}</small><strong>{value}</strong></div>)}</div><div className="eng-report-grid"><div><h4>Journey outcomes</h4>{['Active','Paused','Completed','Cancelled'].map(s=><div className="eng-report-bar" key={s}><span>{s}</span><div><i style={{width:(runs.length?runs.filter((r:any)=>r.data.status===s).length/runs.length*100:0)+'%'}}/></div><strong>{runs.filter((r:any)=>r.data.status===s).length}</strong></div>)}</div><div><h4>Recorded milestone associations</h4><div className="eng-stat-grid"><div><small>Mentor Sessions booked</small><strong>{attributions.filter((r:any)=>r.data.milestone==='Mentor Session booked').length}</strong></div><div><small>Student enrollments</small><strong>{attributions.filter((r:any)=>r.data.milestone==='Student enrolled').length}</strong></div></div><p className="muted">Last CRM campaign submission before a milestone, within the campaign’s configured window. Attribution does not establish causation.</p></div></div></Panel><div className="eng-two-col"><Panel title="AI & conversation handling" detail="Explicit conversation states and verified action history."><div className="eng-stat-grid">{[['AI enabled',c.of('conversation').filter((r:any)=>r.data.state==='AI').length],['Human handling',c.of('conversation').filter((r:any)=>r.data.state==='Human').length],['Callbacks recorded',c.of('callback').length],['Confirmed bookings',c.of('booking').filter((r:any)=>r.data.status==='Booked').length]].map(([name,value])=><div key={name}><small>{name}</small><strong>{value}</strong></div>)}</div><p className="muted">AI-generated qualification proposals require explicit student confirmation. Booking requests are excluded from confirmed bookings.</p></Panel><Panel title="Meta conversion delivery" detail="Acceptance, attribution and optimization are separate states."><div className="eng-stat-grid">{[['Pending',filtered.filter((j:any)=>j.kind==='meta'&&['queued','retry','blocked'].includes(j.status)).length],['Accepted',filtered.filter((j:any)=>j.kind==='meta'&&j.status==='accepted'&&!j.data.providerTest).length],['Provider test accepted',filtered.filter((j:any)=>j.kind==='meta'&&j.status==='accepted'&&j.data.providerTest).length],['Failed / suppressed',filtered.filter((j:any)=>j.kind==='meta'&&['failed','suppressed'].includes(j.status)).length]].map(([name,value])=><div key={name}><small>{name}</small><strong>{value}</strong></div>)}</div><p className="muted">Advertising attribution and optimization eligibility must be verified in Meta. Provider-reported costs, email opens/clicks and WhatsApp read signals appear only when available; privacy tools and scanners can affect measurements.</p></Panel></div><ProviderSignals from={from} to={to}/><Panel title="Recipient and job history" detail="Inspect current state, original due time, provider IDs and failure reasons."><JobTable/></Panel>{c.admin&&<><RunnerPanel/><SyncDiagnostics/></>}</>;}

function ProviderSignals({from,to}:any){
 const c=useEng(),limited=!!(from||to),inRange=(d:string)=>(!from||d.slice(0,10)>=from)&&(!to||d.slice(0,10)<=to),jobs=c.jobs.filter((j:any)=>inRange(j.created_at)),events=c.events.filter((e:any)=>inRange(e.created_at));
 const metric=(type:string)=>limited?events.filter((e:any)=>e.type===type).length:(c.metrics||[]).find((r:any)=>r.type===type)?.count||0;
 const states=(campaignId:string)=>limited?jobs.filter((j:any)=>j.data.campaignId===campaignId).reduce((o:any,j:any)=>(o[j.status]=(o[j.status]||0)+1,o),{}):(c.campaignCounts||[]).filter((r:any)=>r.campaignId===campaignId).reduce((o:any,r:any)=>(o[r.status]=r.count,o),{});
 const costs=limited?Object.entries(jobs.reduce((o:any,j:any)=>{if(typeof j.result.providerCost==='number'&&j.result.currency)o[j.result.currency]=(o[j.result.currency]||0)+j.result.providerCost;return o;},{})).map(([currency,amount])=>({currency,amount})):c.costs||[];
 return <Panel title="Channel signals & campaign delivery" detail={limited?'Date-filtered signals use the latest 300 events and 500 jobs.':'All-time provider signal and campaign state counts cover the full store.'}>
 <div className="eng-stat-grid six">{[['WhatsApp reads',metric('Provider read')],['WhatsApp replies',metric('WhatsApp received')],['Email opens',metric('email.opened')],['Email clicks',metric('email.clicked')],['Email bounces',metric('email.bounced')],['Email unsubscribes',metric('Email unsubscribed')],['Email complaints',metric('email.complained')],['Email replies',metric('email.replied')],['SMS replies',metric('SMS reply')],['SMS opt-outs',metric('SMS unsubscribed')],['Tracked link visits',metric('Tracked link click')]].map(([label,value])=><div key={label}><small>{label}</small><strong>{value}</strong></div>)}</div>
 <p className="muted">Opens and clicks are provider-reported events; privacy tools and scanners affect accuracy. Replies include all inbound WhatsApp messages. Campaign associations appear in the milestone report.</p>
 <Table><TableHeader><TableRow>{['Campaign','Queued','Submitted','Delivered / read','Failed','Suppressed / cancelled'].map(v=><TableHead key={v}>{v}</TableHead>)}</TableRow></TableHeader><TableBody>{c.of('campaign').map((r:any)=>{const s=states(r.id);return <TableRow key={r.id}><TableCell><button className="text-button" onClick={()=>c.setInspect({type:'campaign',record:r})}>{r.data.name}</button></TableCell><TableCell>{(s.queued||0)+(s.retry||0)+(s.blocked||0)}</TableCell><TableCell>{s.submitted||0}</TableCell><TableCell>{(s.delivered||0)+(s.read||0)}</TableCell><TableCell>{s.failed||0}</TableCell><TableCell>{(s.suppressed||0)+(s.cancelled||0)}</TableCell></TableRow>;})}</TableBody></Table>
 {!c.of('campaign').length&&<Empty>Saved broadcasts and their provider states appear here.</Empty>}
 <p className="muted">Provider-reported costs: {costs.length?costs.map((v:any)=>Number(v.amount).toFixed(2)+' '+v.currency).join(' · '):'Not supplied by connected providers'}. No estimated charges are presented as billed amounts.</p>
 </Panel>;
}

function MetaEventTest(){const c=useEng(),[leadId,setLeadId]=useState(''),[milestone,setMilestone]=useState('Inquiry received');return <div className="eng-disclosure"><h4>Meta Test Events check</h4><p className="muted">Choose an isolated test student with Meta consent. This queues an actual provider Test Events request using the configured code; it is separate from a local dry run and live conversions.</p><div className="eng-form-grid"><Field label="Test student"><Select label="Meta test student" value={leadId} onChange={setLeadId} options={[{value:'',label:'Choose isolated student'},...c.leads.map((r:any)=>({value:r.id,label:r.data.name}))]}/></Field><Field label="Milestone"><Select label="Meta test milestone" value={milestone} onChange={setMilestone} options={[...milestones]}/></Field></div><button className="btn" disabled={!leadId||c.busy} onClick={()=>c.act({action:'metaTest',leadId,milestone,requestId:requestId()},'Meta Test Events check queued; inspect Jobs & diagnostics')}>Queue provider test event</button></div>;}
